using Meziantou.Framework.Imaging.TestHarness.Adapters;
using Meziantou.Framework.Imaging.TestHarness.Fixtures;
using Meziantou.Framework.Imaging.TestHarness.Golden;
using Meziantou.Framework.Imaging.TestHarness.Pixels;
using Meziantou.Framework.Imaging.TestHarness.Tga;

namespace Meziantou.Framework.Imaging.Tests.Conformance;

/// <summary>
/// TGA decoding against the corpus generated by <c>tools/Meziantou.Framework.Imaging.CorpusGenerator/TgaCorpus.cs</c>: files assembled
/// byte by byte with literal pixels, plus a file produced by FFmpeg's independent TGA encoder. These tests check that the
/// fixtures cover every supported image type, depth, origin and packet kind, that decoding is exact, that an undeclared
/// alpha channel is never read as transparency, that truncation before the end of the image data always fails, and that
/// the independent harness reader agrees with the corpus and rejects every malformed fixture.
/// </summary>
public sealed class TgaDecoderConformanceTests
{
    public static TheoryData<string> ValidFixtures => [.. GoldenCorpus.Default.GetIds(format: "tga", kind: FixtureKinds.Valid)];

    public static TheoryData<string> InvalidFixtures => [.. GoldenCorpus.Default.GetIds(format: "tga", kind: FixtureKinds.Invalid)];

    [Fact]
    public void FixturesCoverEveryDocumentedVariant()
    {
        var fixtures = GoldenCorpus.Default.GetIds(format: "tga", kind: FixtureKinds.Valid).Select(GoldenCorpus.Default.Get).ToList();
        var features = fixtures.SelectMany(fixture => fixture.Entry.Features ?? []).ToHashSet(StringComparer.Ordinal);
        foreach (var feature in new[]
        {
            "tga.imageType=1", "tga.imageType=2", "tga.imageType=3", "tga.imageType=10", "tga.imageType=11",
            "tga.depth=8", "tga.depth=15", "tga.depth=16", "tga.depth=24", "tga.depth=32",
            "tga.alphaBits=0", "tga.alphaBits=1", "tga.alphaBits=8",
            "tga.rowOrder=bottom-up", "tga.rowOrder=top-down", "tga.columnOrder=left-to-right", "tga.columnOrder=right-to-left",
            "tga.colorMap.offset", "tga.rle.run", "tga.rle.raw", "tga.rle.packet=128", "tga.rle.crossesRow",
            "tga.idField", "tga.footer", "tga.width=odd",
        })
        {
            Assert.Contains(feature, features);
        }

        Assert.Contains(fixtures, fixture => fixture.Entry.Provenance.Origin == "hand-authored");
        Assert.Contains(fixtures, fixture => fixture.Entry.Provenance.Commands?.Any(command => command.StartsWith("ffmpeg", StringComparison.Ordinal)) == true);
        Assert.All(fixtures, fixture => Assert.True(fixture.Policy.IsExact, fixture.Id));
    }

    [Theory]
    [MemberData(nameof(ValidFixtures))]
    public void DecodingIsExactInEveryRepresentation(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();

        using (var image = Image.Load<Rgba32>(data))
        {
            var actual = ImageSnapshots.CaptureFrame(image.Frames[0]);
            Assert.True(fixture.GetFrame(0, RawPixelLayout.Rgba8).Span.SequenceEqual(actual.Span), $"{id}: differs from the reference.");
        }

        using (var image = Image.Load(data))
        {
            Assert.Equal(fixture.Expected.PixelFormat, image.PixelFormat.ToString());
            var layout = image.PixelFormat switch
            {
                PixelFormat.Gray8 => RawPixelLayout.Gray8,
                PixelFormat.Rgb24 => RawPixelLayout.Rgb8,
                _ => RawPixelLayout.Rgba8,
            };

            var bytes = new byte[image.Width * image.Height * layout.BytesPerPixel];
            image.Frames[0].CopyPixelBytesTo(bytes);
            Assert.True(fixture.GetFrame(0, layout).Span.SequenceEqual(bytes), $"{id}: the {layout.Name} samples differ from the reference.");
        }
    }

    [Fact]
    public void AnUndeclaredAlphaChannelIsNotTransparency()
    {
        // The same 32-bit payload decodes to Rgba32 with eight declared alpha bits and to opaque Rgb24 with none
        var declared = Image.Identify(GoldenCorpus.Default.Get("tga/truecolor32-alpha").ReadInput());
        var undeclared = Image.Identify(GoldenCorpus.Default.Get("tga/truecolor32-unspecified-alpha").ReadInput());
        Assert.Equal(PixelFormat.Rgba32, declared.PixelFormat);
        Assert.Equal(PixelFormat.Rgb24, undeclared.PixelFormat);
        Assert.True(declared.MayHaveTransparency);
        Assert.False(undeclared.MayHaveTransparency);
    }

    [Theory]
    [MemberData(nameof(ValidFixtures))]
    public void TruncationBeforeTheEndOfTheImageDataAlwaysFails(string id)
    {
        // TGA has no end-of-image marker: a prefix that holds the whole raster is a valid TGA 1.0 file (the trailing bytes
        // of a TGA 2.0 file are never read), so only the prefixes shorter than the image data must fail
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var imageDataLength = data.Length - ReferenceTga.Parse(data).TrailingBytes;
        for (var length = 0; length < imageDataLength; length++)
        {
            var length2 = length;
            var exception = Record.Exception(() => Image.Load(data.AsSpan(0, length2)).Dispose());
            Assert.True(exception is InvalidImageContentException or UnknownImageFormatException,
                $"{id} truncated to {length} of {imageDataLength} bytes: {exception?.GetType().Name ?? "no exception"}.");
        }

        // From the end of the image data on, every prefix is a complete image with the same pixels
        for (var length = imageDataLength; length <= data.Length; length++)
        {
            using var image = Image.Load<Rgba32>(data.AsSpan(0, length));
            Assert.True(fixture.GetFrame(0, RawPixelLayout.Rgba8).Span.SequenceEqual(ImageSnapshots.CaptureFrame(image.Frames[0]).Span),
                $"{id} with {data.Length - length} trailing bytes removed differs from the reference.");
        }
    }

    [Theory]
    [MemberData(nameof(ValidFixtures))]
    public void TheReferenceReaderAgreesWithTheCorpus(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        var reference = ReferenceTga.Parse(fixture.ReadInput());
        Assert.Equal((fixture.Expected.Width, fixture.Expected.Height), (reference.Width, reference.Height));
        Assert.True(fixture.GetFrame(0, RawPixelLayout.Rgba8).Span.SequenceEqual(reference.Rgba.Span), $"{id}: the harness reader differs from the corpus reference.");
    }

    [Theory]
    [MemberData(nameof(InvalidFixtures))]
    public void TheReferenceReaderRejectsEveryMalformedFixture(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        Assert.Throws<InvalidDataException>(() => ReferenceTga.Parse(fixture.ReadInput()));
        var exception = Assert.Throws<InvalidImageContentException>(() => Image.Load(fixture.ReadInput()));
        Assert.Equal(ImageFormat.Tga, exception.Format);
    }
}
